const variable = (key: string, label: string, defaultValue: string, options?: string[]): CommandVariable => ({
  key, label, defaultValue, options,
});

const command = (
  id: string,
  category: string,
  title: string,
  description: string,
  value: string,
  options: Partial<DeveloperCommand> = {},
): DeveloperCommand => ({
  id, category, title, description, command: value,
  keywords: options.keywords ?? [], danger: options.danger ?? "safe",
  ...options,
});

const name = variable("name", "Name", "app");
const container = variable("container", "Container", "app-container");
